package ai.mwm.client.data
import org.json.JSONObject
fun decode(root:JSONObject):Preferences {val p=root.optJSONObject("preferences") ?: JSONObject();return Preferences(p.optString("myName", "User 1"), p.optString("partnerName", "User 2"), p.optString("code", "K4T9PB"), p.optBoolean("started"), p.optInt("avatar", -1).let { if(root.optInt("version") < 4 && it == 0 && p.optString("myPhoto").isBlank()) -1 else it }, p.optBoolean("quietEnabled", true), p.optInt("quietStart", 1320), p.optInt("quietEnd", 450), p.optString("style", "Soft purr"), p.optBoolean("sound", true), p.optBoolean("haptics", true), p.optString("myPhoto"), p.optString("partnerPhoto"), p.optBoolean("pokeOptIn"), p.optString("themeMode", "System"), p.optString("language", "en"), p.optLong("codeExpiresAt"), p.optLong("togetherSince", java.time.LocalDate.of(2023,2,14).toEpochDay()), p.optInt("defaultReminderTime",750).coerceIn(0,1439), p.optBoolean("keepResetHistory",true), true,p.optString("clockZone"),"",p.optString("partnerClockOverride"),p.optString("listLayout","Wide"))}
fun encode(p:Preferences):JSONObject = JSONObject().put("myName", p.myName).put("partnerName", p.partnerName).put("code", p.code).put("started", p.started).put("avatar", p.avatar).put("quietEnabled", p.quietEnabled).put("quietStart", p.quietStart).put("quietEnd", p.quietEnd).put("style", p.style).put("sound", p.sound).put("haptics", p.haptics).put("myPhoto", p.myPhoto).put("partnerPhoto", p.partnerPhoto).put("pokeOptIn", p.pokeOptIn).put("themeMode", p.themeMode).put("language", p.language).put("codeExpiresAt", p.codeExpiresAt).put("togetherSince", p.togetherSince).put("defaultReminderTime", p.defaultReminderTime).put("keepResetHistory",p.keepResetHistory).put("shareProfile",true).put("clockZone",p.clockZone).put("partnerClockOverride",p.partnerClockOverride).put("listLayout",p.listLayout)
fun main() {
 val old=decode(JSONObject("{\"version\":4,\"preferences\":{\"myName\":\"Kris\",\"shareProfile\":false}}"))
 check(old.myName=="Kris" && old.shareProfile && old.listLayout=="Wide" && old.clockZone.isBlank())
 val next=Preferences(myName="Kris",clockZone="Europe/Berlin",partnerClockOverride="Asia/Tokyo",listLayout="Grid",togetherSince=20000)
 val roundtrip=decode(JSONObject().put("version",4).put("preferences",encode(next)))
 check(roundtrip.clockZone==next.clockZone && roundtrip.partnerClockOverride==next.partnerClockOverride && roundtrip.listLayout=="Grid" && roundtrip.togetherSince==20000L)
 println("2 actual preference codec checks passed: old-data compatibility and new-settings round-trip")
}
